function balancePositiveRecordPositions(worlds) {
  for (const [index, world] of worlds.entries()) {
    const orderedIds = world.records.map(record => record.id).sort((a, b) => a.localeCompare(b, 'en'));
    const positive = world.records.filter(record => record.support.every(Boolean));
    if (positive.length !== 1) throw new Error(`${world.slug}: expected one positive before ID balancing`);
    const positiveSlot = positiveSlotByWorld[index];
    const assigned = new Map([[positive[0], orderedIds[positiveSlot]]]);
    const remaining = orderedIds.filter((_, slot) => slot !== positiveSlot);
    let next = 0;
    for (const record of world.records) if (record !== positive[0]) assigned.set(record, remaining[next++]);
    const replacement = new Map();
    for (const record of world.records) {
      const oldId = record.id;
      const newId = assigned.get(record);
      const numeric = /(\d+)$/.exec(oldId)?.[1];
      if (!numeric) throw new Error(`${world.slug}/${oldId}: expected a numeric record suffix`);
      replacement.set(oldId, newId);
      for (const prefix of companionIdPrefixes[world.slug] ?? []) replacement.set(`${prefix}${numeric}`, `${prefix}${/(\d+)$/.exec(newId)[1]}`);
    }
    const patterns = [...replacement.keys()].sort((a, b) => b.length - a.length).map(value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
    const remap = new RegExp(patterns.join('|'), 'g');
    for (const record of world.records) {
      record.text = record.text.replace(remap, value => replacement.get(value));
      record.id = assigned.get(record);
    }
    const lexicallyRanked = [...world.records].sort((a, b) => a.id.localeCompare(b.id, 'en'));
    world.positive_position_lexical = lexicallyRanked.findIndex(record => record.support.every(Boolean)) + 1;
    if (world.positive_position_lexical !== positiveSlot + 1)
      throw new Error(`${world.slug}: positive ID permutation missed requested lexical position`);
  }
}
